package android.database.sqlite;import android.content.Context;
public abstract class SQLiteOpenHelper implements AutoCloseable {private final String path;private final int version;private SQLiteDatabase database;public SQLiteOpenHelper(Context context,String name,SQLiteDatabase.CursorFactory factory,int version){if(factory!=null||name==null||version<1)throw new UnsupportedOperationException("Unsupported database setup");this.path=name;this.version=version;}
 public synchronized SQLiteDatabase getWritableDatabase(){if(database!=null)return database;SQLiteDatabase db=new SQLiteDatabase(path);try{onConfigure(db);int old=db.getVersion();if(old!=version){db.beginTransaction();try{if(old==0)onCreate(db);else if(old<version)onUpgrade(db,old,version);else throw new UnsupportedOperationException("Downgrade unsupported");db.setVersion(version);db.setTransactionSuccessful();}finally{db.endTransaction();}}database=db;return db;}catch(RuntimeException e){db.close();throw e;}}
 public SQLiteDatabase getReadableDatabase(){return getWritableDatabase();}public void onConfigure(SQLiteDatabase db){}public abstract void onCreate(SQLiteDatabase db);public abstract void onUpgrade(SQLiteDatabase db,int oldVersion,int newVersion);public synchronized void close(){if(database!=null){database.close();database=null;}}}
